evaluation_scripts.extractProductList:
() => {
  const cards = document.querySelectorAll('article.product-card, div.product-card');
  const products = [];
  cards.forEach(card => {
    try {
      const link = card.querySelector('a.product-card__link, a[href*="/catalog/"]')?.href;
      const title = card.querySelector('span.product-card__name, span.product-card__brand, h3.product-card__name')?.textContent?.trim();
      const brand = card.querySelector('span.product-card__brand')?.textContent?.trim();
      const priceText = card.querySelector('ins.price__lower-price, span.price__lower-price, span.product-card__price')?.textContent?.trim();
      const price = priceText ? parseInt(priceText.replace(/[^\d]/g, '')) : null;
      const oldPriceText = card.querySelector('del.price__old-price, del.product-card__price-old')?.textContent?.trim();
      const oldPrice = oldPriceText ? parseInt(oldPriceText.replace(/[^\d]/g, '')) : null;
      const ratingText = card.querySelector('span.product-card__rating, span.address-rate-mini')?.textContent?.trim();
      const rating = ratingText ? parseFloat(ratingText.replace(',', '.')) : null;
      const reviewsText = card.querySelector('span.product-card__count, span.address-rate-mini + span')?.textContent?.trim();
      const reviewsCount = reviewsText ? parseInt(reviewsText.replace(/[^\d]/g, '')) : 0;
      const image = card.querySelector('img.product-card__img, img[class*="product-card__img"]')?.src;
      if (link && title) {
        products.push({ link, title, brand, price, oldPrice, rating, reviewsCount, image });
      }
    } catch (e) {}
  });
  return products;
}

evaluation_scripts.extractProductDetails:
() => {
  const result = {};
  try {
    result.title = document.querySelector('h1.product-page__title, h1.product-page__header')?.textContent?.trim();
    const priceEl = document.querySelector('span.price-block__price, ins.price-block__price');
    result.price = priceEl ? parseInt(priceEl.textContent?.replace(/[^\d]/g, '')) : null;
    const oldPriceEl = document.querySelector('del.price-block__old-price, del.price-block__old-price');
    result.oldPrice = oldPriceEl ? parseInt(oldPriceEl.textContent?.replace(/[^\d]/g, '')) : null;
    const ratingEl = document.querySelector('span.product-page__rating, span.product-page__rating-value');
    result.rating = ratingEl ? parseFloat(ratingEl.textContent?.replace(',', '.')) : null;
    const reviewsLink = document.querySelector('a[href*="feedbacks"], a:has-text("Отзывы")');
    result.reviewsCount = reviewsLink ? parseInt(reviewsLink.textContent?.replace(/[^\d]/g, '')) : 0;
    result.reviewsUrl = reviewsLink?.href;

    // Characteristics
    const chars = {};
    const charContainer = document.querySelector('div.product-page__characteristics, div[class*="characteristics"]');
    if (charContainer) {
      charContainer.querySelectorAll('tr, div[class*="characteristic"]').forEach(row => {
        const name = row.querySelector('th, td:first-child, span[class*="name"]')?.textContent?.trim();
        const value = row.querySelector('td:last-child, span[class*="value"]')?.textContent?.trim();
        if (name && value) chars[name] = value;
      });
    }
    result.characteristics = chars;

    // Availability
    const availText = document.body.innerText;
    if (availText.includes('В наличии')) result.availability = 'В наличии';
    else if (availText.includes('Нет в наличии')) result.availability = 'Нет в наличии';
    else result.availability = 'Unknown';

    // Seller & Brand
    result.seller = document.querySelector('a[href*="seller"], a[href*="sellerId"]')?.textContent?.trim();
    result.brand = document.querySelector('span.product-page__brand, a[href*="brand"]')?.textContent?.trim();

    // Article
    const articleMatch = document.body.innerText.match(/Артикул[^\d]*(\d+)/);
    result.article = articleMatch ? articleMatch[1] : null;

    // Images
    result.images = Array.from(document.querySelectorAll('img.slide__img, img[class*="slide__img"]')).map(img => img.src);

    // Sizes & Colors
    result.sizes = Array.from(document.querySelectorAll('button[class*="size"], label[class*="size"]')).map(el => el.textContent?.trim()).filter(Boolean);
    result.colors = Array.from(document.querySelectorAll('button[class*="color"], label[class*="color"]')).map(el => el.getAttribute('title') || el.textContent?.trim()).filter(Boolean);
  } catch (e) {}
  return result;
}

evaluation_scripts.extractReviews:
() => {
  const reviews = [];
  try {
    const items = document.querySelectorAll('li[class*="feedback"], div[class*="feedback"]');
    items.forEach(item => {
      try {
        const ratingEl = item.querySelector('span[class*="rating"], span.address-rate-mini');
        let rating = null;
        if (ratingEl) {
          const style = ratingEl.getAttribute('style');
          if (style && style.includes('width')) {
            const match = style.match(/width:\s*(\d+)%/);
            if (match) rating = parseInt(match[1]) / 20;
          } else {
            rating = parseFloat(ratingEl.textContent?.replace(',', '.').trim());
          }
        }
        const text = item.querySelector('p[class*="text"], span[class*="text"]')?.textContent?.trim();
        const dateEl = item.querySelector('span[class*="date"], time');
        const date = dateEl ? dateEl.dateTime || dateEl.textContent?.trim() : null;
        if (text) reviews.push({ rating, text, date });
      } catch (e) {}
    });
  } catch (e) {}
  return reviews.slice(0, 5);
}
